effect.shader:
void main() {
vec2 uv = acScreenNorm;
vec4 base = texture2DCv(inputImg.texture, uv);
vec3 halo = vec3(0.0);
float w = 0.0;
for(int i=-4; i<=4; i++) {
for(int j=-4; j<=4; j++) {
vec2 offset = vec2(float(i), float(j)) * spread * 0.25;
vec4 s = texture2DCv(inputImg.texture, uv + offset);
float luma = dot(s.rgb, vec3(0.299, 0.587, 0.114));
if (luma > threshold) {
halo += s.rgb * (1.0 - length(vec2(float(i), float(j)))/5.65);
w += 1.0;
}
}
}
if (w > 0.0) halo /= w;
base.r = min(1.0, base.r + halo.r * intensity);
gl_FragColor = base;
}
